// === Tab: mySketch ===
let skeTex = [];
const TEXNUM = 6;
let gra;
const CYCLE = 200;
let lapse = 0;    // mouse timer

function preload(){
	for(let i = 0; i < TEXNUM; i++){
		skeTex[i] = loadImage("https://openprocessing.org/sketch/998417/files/suketchTex_" + i + ".jpg");
	}
}

function setup() {
	createCanvas(4/3*windowHeight, windowHeight,WEBGL);
	//img
	gra = createGraphics(width,height,WEBGL);
	gra.directionalLight(255,255,255,1,1,-1);
	gra.ambientLight(10);
	gra.noStroke();


	noStroke();	
	rectMode(CENTER);
	//shader
	sh = createShader(vert,frag);
	this.shader(sh);
	pixelDensity(1);
	sh.setUniform("u_imgResolution", [gra.width,gra.height]);
	sh.setUniform("u_img",gra);
	for(let i = 0; i < skeTex.length; i++)sh.setUniform("u_tex_" + i, skeTex[i]);

}

function draw() {	
	translate(-20,10,160);
	test2()
	//test();


	if(frameCount%8 == 0)sh.setUniform("u_offset",random());	
	background(0);
	rect(0,0,width, height);
}


function test2(){
	let fr = ( frameCount % CYCLE ) / CYCLE;
	let size = max(width, height)*0.47;
	let step = size/5;
	const ns = 0.005;
	gra.clear();
	gra.background(255,200,255);
	gra.push();
	gra.rotateY(0.5);
	gra.rotateX(0.5);
	for(let z = -size/2; z < size/2; z+= step){
		for(let y = -size/2; y < size/2; y+= step){
			for(let x = -size/2; x < size/2; x+= step){
				let nv = noise(x * ns,y * ns + cos(fr*TAU) , z*ns + sin(fr*TAU));
				var size = (pow(nv,1.5)*3 + sin(fr*TAU)*0.0 + 0.0) * step /2;
				gra.push();
				gra.translate(x+ step/2,y+ step/2, z + step/2);
				gra.sphere(size);
				gra.pop();
			}
		}
	}
	gra.pop();

}

