	gra.clear();
	gra.background(255);
	gra.fill(255,200,200);
	gra.push();
  gra.translate(-spanX, -spanY, 0);
  gra.push();
  gra.rotateZ(frameRad);
  gra.rotateX(frameRad);
  gra.rotateY(frameRad);
  gra.plane(size);
