var vert = `
		precision highp float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;
		uniform float u_time;

    void main() {
      vec3 pos = aPosition;
			vec4 posOut = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);
      gl_Position = posOut;

      // set out value
      var_vertPos      = pos;
      var_vertNormal   =  aNormal;
      var_vertTexCoord = vec2(aTexCoord.x, aTexCoord.y);
    }
`;


var frag = `

precision highp float;

#define PI 3.14159265359

//uniform
uniform vec2 u_imgResolution;
uniform vec2 u_mouse;
uniform float u_time;
uniform float u_offset;
uniform sampler2D u_img;
uniform sampler2D u_tex_0;
uniform sampler2D u_tex_1;
uniform sampler2D u_tex_2;
uniform sampler2D u_tex_3;
uniform sampler2D u_tex_4;
uniform sampler2D u_tex_5;

//attributes, in
varying vec3 var_vertNormal;
varying vec2 var_vertTexCoord;
varying vec3 var_vertPos;



//noise
float random (in vec2 st) {
   	highp float a = 12.9898;
    highp float b = 78.233;
    highp float c = 43758.5453;
    highp float dt= dot(st.xy ,vec2(a,b));
    highp float sn= mod(dt,3.14);
    return fract(sin(sn) * c);
}

float noise(vec2 st) {
    vec2 i = vec2(0.);
		i = floor(st);
    vec2 f = vec2(0.);
		f = fract(st);
    vec2 u =  vec2(0.);
		u = f*f*(3.0-2.0*f);
    return mix( mix( random( i + vec2(0.0,0.0) ),
                     random( i + vec2(1.0,0.0) ), u.x),
                mix( random( i + vec2(0.0,1.0) ),
                     random( i + vec2(1.0,1.0) ), u.x), u.y);
}


//
float grayScale(float r,float g,float b)
{
    float v = 0.30*r + 0.59*g + 0.11*b;
    return v;
}

float sampTex(sampler2D img, float tileNum){
	vec2 texUv = vec2(var_vertTexCoord.x + u_offset, (var_vertTexCoord.y + u_offset) / u_imgResolution.x * u_imgResolution.y);

	texUv += noise(var_vertTexCoord * 30.0)*0.002;
	texUv = fract(texUv * tileNum);
	float texImg = texture2D(img, texUv).r;
	return texImg;
}

float skeImage2(float img){
	float tileNum = 5.0;
	float ratio = float(${TEXNUM})   * img;
	int index = int(ratio);
	float mixRatio = img < 1.0 ? fract(ratio) : 1.0;
	float tex1 = index < 1 ? sampTex(u_tex_0,tileNum) : 
index < 2 ? sampTex(u_tex_1,tileNum) : 
index < 3 ? sampTex(u_tex_2,tileNum) : 
index < 4 ? sampTex(u_tex_3,tileNum) :
index < 5 ? sampTex(u_tex_4,tileNum) : 
sampTex(u_tex_5,tileNum);

	float tex2 = index < 1 ? sampTex(u_tex_1,tileNum) : 
index < 2 ? sampTex(u_tex_2,tileNum) : 
index < 3 ? sampTex(u_tex_3,tileNum) : 
index < 4 ? sampTex(u_tex_4,tileNum) :
index < 5 ? sampTex(u_tex_5,tileNum) : 
1.0;
	return mix(tex1, tex2, mixRatio);
}


void main() {
	vec3 img = texture2D(u_img, var_vertTexCoord).rgb;
	float imgGray = grayScale(img.r, img.g, img.b);

	vec3 img2 = texture2D(u_img, var_vertTexCoord + noise(var_vertTexCoord * 50.0)*0.001).rgb;
	float imgGray2 = grayScale(img2.r, img2.g, img2.b);
	float outline = imgGray / (imgGray2+0.0005);
	outline = step(0.85,outline);

	float o = skeImage2(imgGray2) * outline;
	gl_FragColor = vec4(vec3(o), 1.0);
}

`;

